"""Board representation (0x88 mailbox), FEN parsing, and make/unmake."""

START_FEN = "rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1"

# 0x88 helpers ---------------------------------------------------------------

def sq_index(file: int, rank: int) -> int:
    """file 0-7 ('a'-'h'), rank 0-7 ('1'-'8') -> 0x88 index."""
    return rank * 16 + file


def sq_name(sq: int) -> str:
    if sq is None:
        return "-"
    return "abcdefgh"[sq & 7] + str((sq >> 4) + 1)


def valid(sq: int) -> bool:
    return not (sq & 0x88)


A1, E1, H1 = sq_index(0, 0), sq_index(4, 0), sq_index(7, 0)
A8, E8, H8 = sq_index(0, 7), sq_index(4, 7), sq_index(7, 7)


def _parse_sq(text: str):
    if text == "-":
        return None
    return sq_index("abcdefgh".index(text[0]), int(text[1]) - 1)


# Position -------------------------------------------------------------------

class Position:
    __slots__ = ("board", "turn", "castling", "ep", "halfmove", "fullmove",
                 "_stack", "_king")

    def __init__(self):
        self.board = [None] * 128          # 0x88 board; 'PNBRQK' white, lowercase black
        self.turn = "w"
        self.castling = ""                 # subset of "KQkq"
        self.ep = None                     # en-passant target square or None
        self.halfmove = 0
        self.fullmove = 1
        self._stack = []                   # undo information
        self._king = {"w": None, "b": None}

    # -- FEN -----------------------------------------------------------------

    @classmethod
    def from_fen(cls, fen: str) -> "Position":
        pos = cls()
        parts = fen.split()
        if len(parts) < 4:
            raise ValueError(f"bad FEN: {fen!r}")
        rows = parts[0].split("/")
        if len(rows) != 8:
            raise ValueError(f"bad FEN board: {parts[0]!r}")
        for r, row in enumerate(rows):           # rows[0] is rank 8
            rank = 7 - r
            file = 0
            for ch in row:
                if ch.isdigit():
                    file += int(ch)
                elif ch in "PNBRQKpnbrqk":
                    if file > 7:
                        raise ValueError(f"rank overflow in FEN row {row!r}")
                    pos.put(ch, sq_index(file, rank))
                    file += 1
                else:
                    raise ValueError(f"bad FEN char {ch!r}")
            if file != 8:
                raise ValueError(f"bad FEN row length: {row!r}")
        pos.turn = parts[1]
        pos.castling = "" if parts[2] == "-" else parts[2]
        pos.ep = _parse_sq(parts[3])
        if len(parts) >= 5:
            pos.halfmove = int(parts[4])
        if len(parts) >= 6:
            pos.fullmove = int(parts[5])
        return pos

    def to_fen(self) -> str:
        rows = []
        for rank in range(7, -1, -1):
            row, empty = "", 0
            for file in range(8):
                p = self.board[sq_index(file, rank)]
                if p is None:
                    empty += 1
                else:
                    if empty:
                        row += str(empty)
                        empty = 0
                    row += p
            if empty:
                row += str(empty)
            rows.append(row)
        return " ".join([
            "/".join(rows), self.turn,
            self.castling or "-", sq_name(self.ep) if self.ep is not None else "-",
            str(self.halfmove), str(self.fullmove),
        ])

    def put(self, piece: str, sq: int):
        self.board[sq] = piece
        if piece == "K":
            self._king["w"] = sq
        elif piece == "k":
            self._king["b"] = sq

    def king_sq(self, color: str) -> int:
        return self._king[color]

    def __repr__(self):
        lines = []
        for rank in range(7, -1, -1):
            lines.append(" ".join(
                (self.board[sq_index(f, rank)] or ".") for f in range(8)))
        return "\n".join(lines)


