# Attack detection ------------------------------------------------------------

KNIGHT_OFFS = (33, 31, 18, 14, -33, -31, -18, -14)
KING_OFFS = (16, -16, 1, -1, 17, 15, -17, -15)
DIAG_OFFS = (17, 15, -17, -15)
ORTH_OFFS = (16, -16, 1, -1)

WHITE_PAWN_CAPTURES = (-17, -15)   # squares from which a white pawn attacks sq
BLACK_PAWN_CAPTURES = (17, 15)     # squares from which a black pawn attacks sq


def is_attacked(pos: Position, sq: int, by: str) -> bool:
    """Is `sq` attacked by any piece of color `by`?"""
    board = pos.board
    if by == "w":
        for off in WHITE_PAWN_CAPTURES:
            s = sq + off
            if not (s & 0x88) and board[s] == "P":
                return True
        kn, kg, bi, rk, qn = "N", "K", "B", "R", "Q"
    else:
        for off in BLACK_PAWN_CAPTURES:
            s = sq + off
            if not (s & 0x88) and board[s] == "p":
                return True
        kn, kg, bi, rk, qn = "n", "k", "b", "r", "q"

    for off in KNIGHT_OFFS:
        s = sq + off
        if not (s & 0x88) and board[s] == kn:
            return True
    for off in KING_OFFS:
        s = sq + off
        if not (s & 0x88) and board[s] == kg:
            return True
    for off in DIAG_OFFS:
        s = sq + off
        while not (s & 0x88):
            p = board[s]
            if p is not None:
                if p == bi or p == qn:
                    return True
                break
            s += off
    for off in ORTH_OFFS:
        s = sq + off
        while not (s & 0x88):
            p = board[s]
            if p is not None:
                if p == rk or p == qn:
                    return True
                break
            s += off
    return False


def in_check(pos: Position, color: str) -> bool:
    return is_attacked(pos, pos.king_sq(color), "b" if color == "w" else "w")


# Make / unmake ----------------------------------------------------------------
#
# A move is a tuple (frm, to, promo) where promo is None or one of "QRBN".
# Special moves are inferred: en passant (pawn moving diagonally onto the ep
# square), double push (pawn advancing two ranks), castling (king moving two
# files horizontally).

_CASTLE_MASK = {A1: "Q", H1: "K", E1: "KQ", A8: "q", H8: "k", E8: "kq"}


def _strip_castling(castling: str, frm: int, to: int) -> str:
    lost = ""
    for sq in (frm, to):
        lost += _CASTLE_MASK.get(sq, "")
    return "".join(c for c in castling if c not in lost)


def make(pos: Position, move):
    frm, to, promo = move
    board = pos.board
    piece = board[frm]
    color = "w" if piece.isupper() else "b"

    captured = board[to]
    captured_sq = to
    is_pawn = piece in ("P", "p")
    new_ep = None

    # En passant capture: remove the pawn on the adjacent square.
    if is_pawn and to == pos.ep and captured is None and (to - frm) % 16 != 0:
        captured_sq = to - 16 if color == "w" else to + 16
        captured = board[captured_sq]
        board[captured_sq] = None

    # Double pawn push sets the ep target square.
    if is_pawn and abs(to - frm) == 32:
        new_ep = (frm + to) // 2

    placed = piece
    if promo:
        placed = promo if color == "w" else promo.lower()

    board[frm] = None
    board[to] = placed
    if piece == "K":
        pos._king["w"] = to
        if to - frm == 2:      # O-O: move rook h1 -> f1
            board[H1], board[to - 1] = None, "R"
        elif frm - to == 2:    # O-O-O: rook a1 -> d1
            board[A1], board[to + 1] = None, "R"
    elif piece == "k":
        pos._king["b"] = to
        if to - frm == 2:
            board[H8], board[to - 1] = None, "r"
        elif frm - to == 2:
            board[A8], board[to + 1] = None, "r"

    pos._stack.append((move, captured, captured_sq, pos.ep,
                       pos.castling, pos.halfmove))
    pos.ep = new_ep
    pos.castling = _strip_castling(pos.castling, frm, to)
    pos.halfmove = 0 if (is_pawn or captured) else pos.halfmove + 1
    if color == "b":
        pos.fullmove += 1
    pos.turn = "b" if color == "w" else "w"


def unmake(pos: Position):
    move, captured, captured_sq, ep, castling, halfmove = pos._stack.pop()
    frm, to, promo = move
    board = pos.board
    placed = board[to]
    mover = "white" if placed and placed.isupper() else "black"
    piece = ("P" if mover == "white" else "p") if promo else placed

    board[frm] = piece
    board[to] = None
    if captured is not None:
        cap_piece = captured
        if captured_sq != to:
            pass  # en passant: captured pawn was never on `to`
        board[captured_sq] = cap_piece

    if piece == "K":
        pos._king["w"] = frm
        if to - frm == 2:
            board[H1], board[to - 1] = "R", None
        elif frm - to == 2:
            board[A1], board[to + 1] = "R", None
    elif piece == "k":
        pos._king["b"] = frm
        if to - frm == 2:
            board[H8], board[to - 1] = "r", None
        elif frm - to == 2:
            board[A8], board[to + 1] = "r", None

    pos.ep = ep
    pos.castling = castling
    pos.halfmove = halfmove
    pos.turn = "w" if mover == "white" else "b"
    if pos.turn == "w":
        pos.fullmove -= 1

