"""Legal move generation."""

from .board import (A1, E1, H1, A8, E8, H8, DIAG_OFFS, KING_OFFS,
                    KNIGHT_OFFS, ORTH_OFFS, Position, in_check, is_attacked,
                    sq_name, valid)

KNIGHT, BISHOP, ROOK, QUEEN, KING = "N", "B", "R", "Q", "K"
BACK_RANK = {0: 0, 7: 7}  # promotion ranks handled via rank extraction below


def _rank_of(sq: int) -> int:
    return sq >> 4


def gen_pseudo(pos: Position):
    """Yield pseudo-legal moves as (frm, to, promo) tuples."""
    board = pos.board
    white = pos.turn == "w"
    own_is_upper = str.isupper if white else str.islower
    enemy = "b" if white else "w"

    moves = []
    add = moves.append

    for frm in range(128):
        if frm & 0x88:
            continue
        piece = board[frm]
        if piece is None or not own_is_upper(piece):
            continue

        if piece in ("P", "p"):
            fwd = 16 if white else -16
            start_rank = 1 if white else 6
            last_rank = 7 if white else 0

            one = frm + fwd
            if valid(one) and board[one] is None:
                if _rank_of(one) == last_rank:
                    for pr in "QRBN":
                        add((frm, one, pr))
                else:
                    add((frm, one, None))
                    two = frm + 2 * fwd
                    if _rank_of(frm) == start_rank and board[two] is None:
                        add((frm, two, None))

            for dc in (fwd - 1, fwd + 1):
                to = frm + dc
                if to & 0x88:
                    continue
                target = board[to]
                if target is not None and not own_is_upper(target):
                    if _rank_of(to) == last_rank:
                        for pr in "QRBN":
                            add((frm, to, pr))
                    else:
                        add((frm, to, None))
                elif target is None and pos.ep is not None and to == pos.ep:
                    add((frm, to, None))  # en passant

        elif piece in ("N", "n"):
            for off in KNIGHT_OFFS:
                to = frm + off
                if not (to & 0x88):
                    t = board[to]
                    if t is None or not own_is_upper(t):
                        add((frm, to, None))

        elif piece in ("K", "k"):
            for off in KING_OFFS:
                to = frm + off
                if not (to & 0x88):
                    t = board[to]
                    if t is None or not own_is_upper(t):
                        add((frm, to, None))

        else:
            if piece in ("B", "b"):
                rays = DIAG_OFFS
            elif piece in ("R", "r"):
                rays = ORTH_OFFS
            else:  # queen
                rays = DIAG_OFFS + ORTH_OFFS
            for off in rays:
                to = frm + off
                while not (to & 0x88):
                    t = board[to]
                    if t is None:
                        add((frm, to, None))
                    else:
                        if not own_is_upper(t):
                            add((frm, to, None))
                        break
                    to += off

    # Castling.
    if white:
        if "K" in pos.castling and board[F1] is None and board[G1] is None \
                and board[H1] == "R" \
                and not is_attacked(pos, E1, "b") \
                and not is_attacked(pos, F1, "b") \
                and not is_attacked(pos, G1, "b"):
            add((E1, G1, None))
        if "Q" in pos.castling and board[D1] is None and board[C1] is None \
                and board[B1] is None and board[A1] == "R" \
                and not is_attacked(pos, E1, "b") \
                and not is_attacked(pos, D1, "b") \
                and not is_attacked(pos, C1, "b"):
            add((E1, C1, None))
    else:
        if "k" in pos.castling and board[F8] is None and board[G8] is None \
                and board[H8] == "r" \
                and not is_attacked(pos, E8, "w") \
                and not is_attacked(pos, F8, "w") \
                and not is_attacked(pos, G8, "w"):
            add((E8, G8, None))
        if "q" in pos.castling and board[D8] is None and board[C8] is None \
                and board[B8] is None and board[A8] == "r" \
                and not is_attacked(pos, E8, "w") \
                and not is_attacked(pos, D8, "w") \
                and not is_attacked(pos, C8, "w"):
            add((E8, C8, None))

    return moves


F1, G1, D1, C1, B1 = 5, 6, 3, 2, 1
F8, G8, D8, C8, B8 = 0x75, 0x76, 0x73, 0x72, 0x71


def legal_moves(pos: Position):
    """Fully legal moves: pseudo-legal generation + king-safety filter."""
